AND(
    OR(
        ISCHANGED(Status_de_Gastos__c),
        ISCHANGED(Status_do_Patrocinio__c)
    ),
    NOT(
        OR(
            $Profile.Name = "Compras Financeiro",
            $Profile.Name = "Administração"
        )
    )
)
